<?php
require_once __DIR__.'/v11.php';
function sm_admin(){v11_admin();}
function sm_secret_path(){return dirname(__DIR__,2).'/.eksioglu-mail-secret.php';}
function sm_settings(){ $p=sm_secret_path(); if(!is_file($p))return []; $v=require $p;return is_array($v)?$v:[]; }
function sm_save($data){$path=sm_secret_path();$parent=dirname($path);if(!is_dir($parent)||!is_writable($parent))throw new RuntimeException('Panelin üst klasörüne yazılamıyor. Sunucu yöneticisiyle görüşün.');$tmp=$path.'.'.bin2hex(random_bytes(5));$content='<?php return '.var_export($data,true).';';if(file_put_contents($tmp,$content,LOCK_EX)===false)throw new RuntimeException('Ayar kaydedilemedi.');chmod($tmp,0600);if(!rename($tmp,$path)){@unlink($tmp);throw new RuntimeException('Ayar taşınamadı.');}}
function sm_ready(){try{return (bool)db()->query("SHOW TABLES LIKE 'v112_mail_logs'")->fetchColumn();}catch(Throwable $e){return false;}}
function sm_ehlo($stream){sm_write($stream,"EHLO panel.eksioglulojistik.com");return sm_read($stream,250);}
function sm_read($s,$code){$lines=[];for($i=0;$i<100;$i++){$line=fgets($s,2048);if($line===false)throw new RuntimeException('SMTP bağlantısı kesildi.');$lines[]=rtrim($line);if(preg_match('/^\d{3} /',$line))break;} $last=end($lines);if((int)substr($last,0,3)!==$code)throw new RuntimeException('SMTP sunucusu işlemi reddetti ('.substr($last,0,3).').');return implode("\n",$lines);}
function sm_write($s,$cmd){if(fwrite($s,$cmd."\r\n")===false)throw new RuntimeException('SMTP yazma hatası.');}
function sm_addr($s){if(!filter_var($s,FILTER_VALIDATE_EMAIL)||preg_match('/[\r\n]/',$s))throw new RuntimeException('Geçersiz e-posta adresi.');return $s;}
function sm_header($s){return '=?UTF-8?B?'.base64_encode($s).'?=';}
function sm_send($to,$subject,$body){$cfg=sm_settings();foreach(['host','port','security','username','password','from'] as $k)if(empty($cfg[$k]))throw new RuntimeException('SMTP ayarları tamamlanmamış.');$to=sm_addr($to);$from=sm_addr($cfg['from']);$host=$cfg['host'];$port=(int)$cfg['port'];$mode=$cfg['security'];if(!in_array($mode,['ssl','starttls'],true))throw new RuntimeException('Şifreli SMTP bağlantısı zorunlu.');if(!preg_match('/^[a-zA-Z0-9.-]+$/',$host))throw new RuntimeException('SMTP sunucu adresi geçersiz.');if(!in_array($port,[465,587,2525],true))throw new RuntimeException('Desteklenmeyen SMTP portu.');$context=stream_context_create(['ssl'=>['verify_peer'=>true,'verify_peer_name'=>true,'allow_self_signed'=>false,'peer_name'=>$host]]);$target=($mode==='ssl'?'ssl://':'tcp://').$host.':'.$port;$s=@stream_socket_client($target,$errno,$errstr,15,STREAM_CLIENT_CONNECT,$context);if(!$s)throw new RuntimeException('SMTP sunucusuna bağlanılamadı.');stream_set_timeout($s,20);try{sm_read($s,220);sm_ehlo($s);if($mode==='starttls'){sm_write($s,'STARTTLS');sm_read($s,220);if(!stream_socket_enable_crypto($s,true,STREAM_CRYPTO_METHOD_TLS_CLIENT))throw new RuntimeException('TLS bağlantısı kurulamadı.');sm_ehlo($s);}sm_write($s,'AUTH LOGIN');sm_read($s,334);sm_write($s,base64_encode($cfg['username']));sm_read($s,334);sm_write($s,base64_encode($cfg['password']));sm_read($s,235);sm_write($s,'MAIL FROM:<'.$from.'>');sm_read($s,250);sm_write($s,'RCPT TO:<'.$to.'>');sm_read($s,250);sm_write($s,'DATA');sm_read($s,354);$headers=['From: '.sm_header('EKŞİOĞLU International Movers').' <'.$from.'>','To: <'.$to.'>','Subject: '.sm_header($subject),'MIME-Version: 1.0','Content-Type: text/plain; charset=UTF-8','Content-Transfer-Encoding: base64','Date: '.date(DATE_RFC2822),'Message-ID: <'.bin2hex(random_bytes(12)).'@'.$host.'>','X-Auto-Response-Suppress: All'];$payload=implode("\r\n",$headers)."\r\n\r\n".chunk_split(base64_encode($body),76,"\r\n");$payload=preg_replace('/^\./m','..',$payload);sm_write($s,$payload."\r\n.");sm_read($s,250);sm_write($s,'QUIT');return true;}finally{fclose($s);}}
function sm_log($qid,$to,$status,$message){$s=db()->prepare('INSERT INTO v112_mail_logs(quote_id,recipient,status,actor_id,detail) VALUES(?,?,?,?,?)');$s->execute([$qid,$to,$status,$_SESSION['uid']??null,mb_substr($message,0,300)]);}
